#!/usr/bin/env python3
"""Turn 35 Wave 83: THE GOALKEEPER'S ACTUAL MODEL, AND DREAM DRAFT AS A TEST SURFACE.

Wave 83's centrepieces:

1. THE GOALKEEPER MODEL, which the corpus carried as a two-stat rule and not as a model.
   GKR is not just "reactions" - it is dive rigidity. GKH is not just "handling" - it is
   positioning, aerial catching, cross clearing AND the dive when pushing the ball away.
   And there is a whole behavioural layer the corpus had missed: the keeper auto-kicks the
   ball away when it is within range and an opponent is about to win it, he sometimes rushes
   out on his own, and 60+ Strength is what stops him falling over at random.

2. THE GK DOCTRINE, stated by a position guide in three words: "All Goalkeepers like to play
   dodge ball." So **never depend on the keeper - he is a luck factor, not a system.** That
   reframes the whole defensive plan: the goals you concede through him are not fixable by
   coaching, which is why the corpus's "never push defenders forward" rule matters more than
   any GK investment.

3. DREAM DRAFT AS A SECOND TEST SURFACE - fresh lineups and balanced pools that do not touch
   your main save. That makes it a second place to answer the device-testable questions, and
   the DLS26 drafts are themed to the live events (World Cup Heroes, Summer Trophy).
"""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w83')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid

def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid

os.makedirs(RAW_DIR,exist_ok=True)

e_gk=new_ev("r/DreamLeagueSoccer 1bxd927 'Guide to Various Positions in DLS24' (6 Apr 2024 - the full GK section: GKR and GKH semantics, the C-button summon, the auto-kick-away behaviour, and the dodge-ball doctrine), r/DreamLeagueSoccer 1co8wi2 'Goalkeeper movement options' (the 60+ strength anti-fall finding, GKH as positioning and aerial clearing, the manual sweeper-keeper role, AI self-rushing, and Donnarumma's fast rush), r/DreamLeagueSoccer 179q1fa (17 Oct 2023 - the GK rush timing rule), r/DreamLeagueSoccer hmya2v (7 Jul 2020 - hold C to call the keeper out, double-tap to drop the ball), r/DreamLeagueSoccer 1bxd5eb 'Dream Draft is extremely disappointing' (6 Apr 2024 - the 40-gem entry against a ~50-gem reward, and the 500-coin/150-gem alternative), bluestacks DLS2024 December update (the Dream Draft structure: limited-time, 75+ players, at least one Star Player, up to 7 rounds, leaderboard rewards for winners, runner-ups and third), gamingonphone DLS25 Dream Points guide (the 18-player draft, every option 75+ plus a Star Player, and the Common-boost DP maxima), apkpure.net DLS26 (Dream Draft as a formation-testing surface that does not affect the main save), YouTube DLS26 Dream Draft titles (World Cup Heroes and Summer Trophy themed drafts; an 82-rated draft as a target), dreamleaguekits.com DLS26 GK guide (rating, reflexes, positioning, height - sign an elite keeper first), LevelWinner DLS24 beginner guide (15 Mar 2024 - the outer-foot shooting technique), TikTok DLS26 penalty-save content (the kicker's foot, movement speed and head direction as the read), airsculpt.com and eliselegrow.com (AI content farms carrying the same '22 Tips' article), soccer-zero.wiki, footymeta.com, levelup.soccer, topgoalkeeping.com, u7buy.com (real-football and other-game GK guides - CONTAMINATION)",
    "THE GOALKEEPER'S ACTUAL MODEL, THE GK DOCTRINE, AND DREAM DRAFT AS A TEST SURFACE. (1) THE TWO STATS, defined properly rather than by name: '**GKR** refers to Goalkeeper Reactions, which are useful for the goalkeeper when diving to save a shot. **The higher the stat, the lower the rigidity of the keeper.**' '**GKH** refers to Goalkeeper Handling, which is useful for the goalkeeper when trying to catch a ball or knock the ball away. **Also helps in diving in the case of pushing away the ball.**' So GKR governs the dive and GKH governs the catch, the punch, the positioning and the aerial clearance - a second source confirms it: 'The GK catching the ball in the air, goalkeeper positioning all falls under GKH actually. The higher the GKH the better positioning he will have. GK with higher Handling also clears those Crosses and Corners from air better.' The corpus's GKR>GKH rule therefore has a reason, not just a preference: **GKR >= GKH on any keeper, but too low GKH is not appreciable.** (2) THE BEHAVIOURAL LAYER, entirely new: '**Use the C button to summon the goalkeeper manually while opponent in possession. GK automatically kicks the ball away when it is between kicking range and opponent is in cue to win possession ahead of your defender.**' So the keeper has an auto-clearance behaviour that can be triggered accidentally. 'As for Sweeper keeper that has to be done manually by the player most of the times holding C. **Although Goalkeepers do rush on their own by game AI from time to time. Some GKs have better rush system in built in game than others. Like Donnarumma rushes forward very quickly in my experience.**' - so rushing is partly a per-player AI trait, and Donnarumma is the named case. (3) THE 60+ STRENGTH FINDING: 'If your goalkeeper has at least 60+ strength, they should most of the time win the ball in the air easier, and also **not cause them to fall randomly whenever the opponent has the ball.**' So GK Strength is an anti-fall and aerial stat, which is a recruitment constraint the corpus did not carry. (4) THE GK DOCTRINE, the wave's most useful line: '**All Goalkeepers like to play dodge ball, just for your information.**' and '**Never depend on GKs, keep them as a luck factor.**' So the keeper is not a system you can invest your way out of - which is the argument for the corpus's defensive rules over any GK spend. (5) THE RUSH TIMING RULE: 'if the striker or whoever gets behind the defense, you can hold C to have your goalie run out of the box. **I generally wait until they're almost to the box before holding it**, and I'd say it saves me about a goal once every couple of games.' So rush LATE, not early - and the expected yield is about one goal saved every two games. (6) THE SUMMON AND RELEASE CONTROLS, corroborated across three years: hold C to call the keeper out, double-tap on the keeper to drop the ball from his hands. (7) THE PENALTY-SAVE READ, the defensive counterpart to the corpus's offensive penalty technique: read the kicker's **foot, movement speed and head direction** to guess placement. (8) GK RECRUITMENT PRIORITY: 'the best goalkeepers are the ones who combine rating, reflexes, positioning, and height... players who want a stable defense usually start by signing an elite goalkeeper first.' (9) THE OUTER-FOOT SHOOTING TECHNIQUE, new to the corpus: 'When shooting with the B button, charge it to 100% for maximum power and speed. **Aim for the outer foot of the imaginary goalkeeper at the side you're shooting at.** As such, the goalkeeper will likely dive sideways and your dead-center shot will be uncontested.' So you aim at the keeper's outer foot to drag him across, then shoot centrally. (10) DREAM DRAFT AS A TEST SURFACE: 'Dream Draft provides fresh lineups and balanced pools, which is useful for testing formations **without affecting your main save**' - a second place to answer the device-testable questions, alongside Exhibition. (11) THE DREAM DRAFT STRUCTURE: limited-time, a draft of 18 players where every option is 75+ plus a Star Player, up to 7 rounds, each round a different opponent, and leaderboard rewards for the winners, runner-ups and third place (medals, gems, coins). (12) THE DREAM DRAFT ECONOMICS, now three-source: entry about 40 gems or 500 coins, a win paying about 50 gems, so the net is often only ~10 gems - 'It cost me 40 gems and the end reward adds upto 50 so basically my profit is just 10 gems', against '500 coins entry, won it three times and won 150 gems in like 2 hours.' (13) DLS26 DREAM DRAFTS ARE THEMED to the live events - World Cup Heroes drafts (Ronaldo, Haaland) and a Summer Trophy draft (Ronaldo, Messi) - and the draft itself has a rating, with an 82-rated draft treated as a target. (14) DRAFT EVENTS PAY CLAN POINTS: 'win live and draft events to earn the most points for your group.' (15) CONTAMINATION, the second instance of the wave-82 pattern: a GK search returns soccer-zero.wiki, footymeta, levelup.soccer, topgoalkeeping and u7buy - real-football and other-game guides. Only r/DLS and the DLS guides are usable, and the contamination is recorded rather than mined.",
    "THE GOALKEEPER'S ACTUAL MODEL: GKR = dive and rigidity (higher = less rigid); GKH = handling, positioning, aerial catching AND cross clearing - so GKR >= GKH, but too-low GKH is not appreciable. THE BEHAVIOURAL LAYER: hold C summons the keeper; the keeper AUTO-KICKS the ball away when it is within range and an opponent is about to win it; he sometimes rushes out on his own, and Donnarumma rushes forward very quickly, so rushing is partly a per-player AI trait. 60+ STRENGTH stops the keeper falling over at random and helps him win aerial balls. THE GK DOCTRINE: 'All Goalkeepers like to play dodge ball' and 'never depend on GKs, keep them as a luck factor' - the keeper is not a system you can invest out of. THE RUSH TIMING RULE: wait until the attacker is almost at the box; the yield is about one goal saved every two games. THE PENALTY-SAVE READ: the kicker's foot, movement speed and head direction. GK RECRUITMENT: rating, GKR, GKH, height, 60+ STR. THE OUTER-FOOT SHOOTING TECHNIQUE: charge B to 100% and aim at the keeper's outer foot to drag him across, then shoot dead centre. DREAM DRAFT is a second test surface - fresh lineups that do not touch the main save - and DLS26 drafts are themed to the live events with an 82-rated draft as a target. Draft economics: 40 gems or 500 coins entry, ~50 gems per win. CONTAMINATION: a GK search returns other games' guides",
    "THE GOALKEEPER'S ACTUAL MODEL, THE GK DOCTRINE, AND DREAM DRAFT AS A TEST SURFACE",
    quality="community")

add_claim("GKR = Goalkeeper Reactions, and it governs the DIVE: 'useful for the goalkeeper when diving to save a shot. The higher the stat, the lower the rigidity of the keeper.' So a high-GKR keeper is less rigid and reacts faster; a low-GKR keeper is slow to move.", 2, "goalkeeping/gkr-dive-rigidity", [e_gk])
add_claim("GKH = Goalkeeper Handling, and it governs far more than catching: 'useful for the goalkeeper when trying to catch a ball or knock the ball away. Also helps in diving in the case of pushing away the ball.' A second source extends it: 'The GK catching the ball in the air, goalkeeper positioning all falls under GKH actually. The higher the GKH the better positioning he will have. GK with higher Handling also clears those Crosses and Corners from air better.' **So GKH is the positioning and aerial-clearance stat, not just a handling one.**", 2, "goalkeeping/gkh-handling-positioning-aerial", [e_gk], notes="Extends the corpus's two-stat GK rule into a real model")
add_claim("The corpus's GKR>GKH rule now has a reason: 'GKR stat is preferable to be higher than GKH stat, but too low GKH is not appreciable' and 'It is widely preferred to have GKR >= GKH on any type of keeper.' So GKR leads, but GKH must not be starved - it is the positioning and aerial stat.", 3, "goalkeeping/gkr-over-gkh-with-the-floor", [e_gk])
add_claim("THE GK AUTO-CLEARANCE BEHAVIOUR, entirely new: 'Use the C button to summon the goalkeeper manually while opponent in possession. **GK automatically kicks the ball away when it is between kicking range and opponent is in cue to win possession ahead of your defender.**' So the keeper has an automatic clearance that can fire at the wrong moment and give the ball away.", 3, "goalkeeping/auto-kick-away-behaviour", [e_gk])
add_claim("THE SWEEPER-KEEPER ROLE IS MANUAL, and AI rushing is partly a per-player trait: 'As for Sweeper keeper that has to be done manually by the player most of the times holding C. Although Goalkeepers do rush on their own by game AI from time to time. **Some GKs have better rush system in built in game than others. Like Donnarumma rushes forward very quickly in my experience.**' So rushing behaviour varies by player, and Donnarumma is the named fast-rush case.", 3, "goalkeeping/manual-sweeper-and-per-keeper-rush-trait", [e_gk])
add_claim("60+ STRENGTH IS A GOALKEEPER CONSTRAINT: 'If your goalkeeper has at least 60+ strength, they should most of the time win the ball in the air easier, and also **not cause them to fall randomly whenever the opponent has the ball.**' So GK Strength is an anti-fall and aerial stat - a recruitment filter the corpus did not carry.", 3, "goalkeeping/strength-60-anti-fall", [e_gk])
add_claim("THE GK DOCTRINE: '**All Goalkeepers like to play dodge ball, just for your information**' and '**Never depend on GKs, keep them as a luck factor.**' So the keeper is not a system you can invest your way out of - which is the argument for the corpus's defensive rules (never push defenders forward, zonal out of possession) over any GK spend.", 3, "goalkeeping/keeper-is-a-luck-factor", [e_gk], notes="Reframes GK investment: coach the defence, not the keeper")
add_claim("THE GK RUSH TIMING RULE: 'if the striker or whoever gets behind the defense, you can hold C to have your goalie run out of the box. **I generally wait until they're almost to the box before holding it**, and I'd say it saves me about a goal once every couple of games.' So rush LATE, and the expected yield is about one goal saved every two matches - which is worth having but not worth risking.", 3, "goalkeeping/rush-late-yield", [e_gk])
add_claim("The summon and release controls, corroborated across three years of sources: **hold C to call the keeper out**, and **double-tap on the keeper to drop the ball from his hands**.", 3, "goalkeeping/summon-and-release-controls", [e_gk], notes="Third source for CLAIM-292")
add_claim("THE PENALTY-SAVE READ, the defensive counterpart to the corpus's offensive penalty technique: read the kicker's **foot, movement speed and head direction** to guess shot placement. Two independent DLS26 creators give the same three cues.", 3, "goalkeeping/penalty-save-read", [e_gk])
add_claim("GK RECRUITMENT PRIORITY: 'the best goalkeepers are the ones who combine **rating, reflexes, positioning, and height**' - which maps to OVR, GKR, GKH and physical height - and 'players who want a stable defense usually start by signing an elite goalkeeper first.'", 3, "goalkeeping/recruitment-priority", [e_gk])
add_claim("THE OUTER-FOOT SHOOTING TECHNIQUE, new to the corpus: 'When shooting with the B button, charge it to 100% for maximum power and speed. **Aim for the outer foot of the imaginary goalkeeper at the side you're shooting at.** As such, the goalkeeper will likely dive sideways and your dead-center shot will be uncontested.' So you aim at the keeper's outer foot to drag him across the goal, then shoot centrally.", 3, "shooting/outer-foot-technique", [e_gk])
add_claim("DREAM DRAFT IS A SECOND TEST SURFACE: 'Dream Draft provides fresh lineups and balanced pools, which is useful for testing formations **without affecting your main save**.' So alongside Exhibition it is a place to answer the device-testable questions - and unlike Exhibition, a draft can pay.", 3, "modes/dream-draft-as-test-surface", [e_gk])
add_claim("THE DREAM DRAFT STRUCTURE: a limited-time tournament mode where you draft a team of 18 players and **every option is 75+ rated, plus a Star Player**; it runs to a maximum of 7 rounds, each against a different opponent, and the leaderboard pays the winners, runner-ups and third place in medals, gems and coins.", 3, "modes/dream-draft-structure-and-rewards", [e_gk])
add_claim("THE DREAM DRAFT ECONOMICS, now three-source: entry is about **40 gems or 500 coins**, a win pays about **50 gems**, so the net is often only ~10 gems - 'It cost me 40 gems and the end reward adds upto 50 so basically my profit is just 10 gems' - against the alternative '500 coins entry, won it three times and won 150 gems in like 2 hours.' **The 500-coin route is the better-value entry for a F2P account.**", 3, "modes/dream-draft-economics-three-source", [e_gk], notes="Extends CLAIM-338 and CLAIM-1343 with the coin-vs-gem entry comparison")
add_claim("DLS26 DREAM DRAFTS ARE THEMED to the live events - World Cup Heroes drafts (Ronaldo, Haaland) and a Summer Trophy draft (Ronaldo, Messi) - and the draft itself carries a rating, with an 82-rated draft treated as a target by players. So the mode rotates with the event calendar rather than running permanently.", 3, "modes/dream-draft-themed-and-rated", [e_gk])
add_claim("DRAFT EVENTS PAY CLAN POINTS: 'win live and draft events to earn the most points for your group' - a third point source alongside matches, challenges and Season Pass tiers.", 3, "clans/draft-events-pay-clan-points", [e_gk])
add_claim("CONTAMINATION, the second instance of the wave-82 pattern: a goalkeeper search returns soccer-zero.wiki, footymeta.com, levelup.soccer, topgoalkeeping.com and u7buy.com - real-football and other-game guides, including FC 26 control lists. Only r/DLS and the DLS-specific guides are usable. Recorded so the pattern is recognised rather than re-mined.", 3, "errata/gk-guide-contamination", [e_df] if False else [e_gk])

for p in ['EV-496_goalkeeper_model.html','EV-496b_dream_draft.html']:
    with open(os.path.join(RAW_DIR,p),'w') as fh: fh.write("placeholder\n")

with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f'Added {cl_id-1-last_cl} claims (CLAIM-{last_cl+1:04d}..CLAIM-{cl_id-1:04d}) and 1 EV (EV-{last_ev+1:03d}). Totals: {n_cl} claims / {n_ev} EVs')
